using RAWSelectionAssistant.Core.Services.Projects;
namespace RAWSelectionAssistant.Views;
public partial class PhotoGradePageView
{
 private Border? cropPanel;private Point? cropStart,cropEnd;private string cropAspect="自由";
 private void CropTool(object sender,RoutedEventArgs e){CancelMaskStroke();activeTool="裁切";ToolLabel.Text="裁切";PhotoViewport.Cursor=Cursors.Cross;if(model?.RawLocalEditing!=true){ToolHint.Text="裁剪当前支持线性RAW版本；其他历史配方保留原边界。";return;}if(cropPanel is not null){cropPanel.Visibility=Visibility.Visible;return;}
  var bar=new WrapPanel();var ratio=new ComboBox{ItemsSource=new[]{"自由","原比例","1:1","4:3","3:2","16:9"},SelectedIndex=0,Width=85};ratio.SelectionChanged+=(_,_)=>cropAspect=ratio.SelectedItem as string??"自由";bar.Children.Add(ratio);
  void Add(string title,Action action){var b=new Button{Content=title};b.Click+=(_,_)=>action();bar.Children.Add(b);}Add("旋转90°",()=>{var g=model!.ActiveTarget!.RawDefinition!.Geometry??new();model.SetRawOutputGeometry(g with{QuarterTurns=(g.QuarterTurns+1)%4});});Add("翻转",()=>{var g=model!.ActiveTarget!.RawDefinition!.Geometry??new();model.SetRawOutputGeometry(g with{FlipHorizontal=!g.FlipHorizontal});});Add("重置",()=>{model?.SetRawOutputGeometry(null);cropStart=cropEnd=null;DrawCrop();});Add("完成",()=>{cropPanel!.Visibility=Visibility.Collapsed;activeTool="选择";ToolLabel.Text="选择";CropOverlay.Children.Clear();});cropPanel=new Border{Child=bar,Background=new SolidColorBrush(Color.FromArgb(230,29,29,32)),Padding=new Thickness(6),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Top,Margin=new Thickness(0,8,0,0)};ViewerArea.Children.Add(cropPanel);Panel.SetZIndex(cropPanel,20);ToolHint.Text="拖动裁剪框 · 选择比例 · 完成";
 }
 private bool CropDown(Point point){if(activeTool!="裁切"||model?.RawLocalEditing!=true||model.Editor.ReadOnlyTarget)return false;var rect=PhotoViewport.State.ImageRect(new Rect(PhotoViewport.RenderSize));if(!rect.Contains(point))return true;cropStart=cropEnd=new(Math.Clamp((point.X-rect.Left)/rect.Width,0,1),Math.Clamp((point.Y-rect.Top)/rect.Height,0,1));PhotoViewport.CaptureMouse();return true;}
 private bool CropMove(Point point){if(activeTool!="裁切"||cropStart is null)return false;var rect=PhotoViewport.State.ImageRect(new Rect(PhotoViewport.RenderSize));cropEnd=new(Math.Clamp((point.X-rect.Left)/rect.Width,0,1),Math.Clamp((point.Y-rect.Top)/rect.Height,0,1));DrawCrop();return true;}
 private bool CropUp(){if(activeTool!="裁切"||cropStart is not{} a||cropEnd is not{} b)return false;PhotoViewport.ReleaseMouseCapture();if(model?.RawLocalEditing!=true||model.Editor.ReadOnlyTarget){cropStart=cropEnd=null;CropOverlay.Children.Clear();return true;}double x=Math.Min(a.X,b.X),y=Math.Min(a.Y,b.Y),w=Math.Abs(a.X-b.X),h=Math.Abs(a.Y-b.Y);if(w<.01||h<.01){cropStart=null;return true;}var g=model!.ActiveTarget!.RawDefinition!.Geometry??new();var size=ProfessionalRawPipeline.OutputSize(model.ActiveTarget.LinearRawMaster!,model.ActiveTarget.RawDefinition);double ratio=cropAspect switch{"1:1"=>1,"4:3"=>4d/3,"3:2"=>1.5,"16:9"=>16d/9,"原比例"=>(double)size.Width/size.Height,_=>0};if(ratio>0){double normalized=ratio*size.Height/size.Width;if(w/h>normalized)w=h*normalized;else h=w/normalized;}
  var corners=new[]{g.Source(x,y),g.Source(x+w,y),g.Source(x,y+h),g.Source(x+w,y+h)};double left=corners.Min(p=>p.X),top=corners.Min(p=>p.Y);model.SetRawOutputGeometry(g with{X=left,Y=top,Width=corners.Max(p=>p.X)-left,Height=corners.Max(p=>p.Y)-top});cropStart=cropEnd=null;CropOverlay.Children.Clear();return true;
 }
 private void DrawCrop(){CropOverlay.Children.Clear();if(cropStart is not{} a||cropEnd is not{} b)return;var r=PhotoViewport.State.ImageRect(new Rect(PhotoViewport.RenderSize));var offset=PhotoViewport.TranslatePoint(new Point(),CropOverlay);var shape=new Rectangle{Width=Math.Abs(a.X-b.X)*r.Width,Height=Math.Abs(a.Y-b.Y)*r.Height,Stroke=Brushes.White,StrokeThickness=1,Fill=new SolidColorBrush(Color.FromArgb(25,110,155,145))};Canvas.SetLeft(shape,r.Left+offset.X+Math.Min(a.X,b.X)*r.Width);Canvas.SetTop(shape,r.Top+offset.Y+Math.Min(a.Y,b.Y)*r.Height);CropOverlay.Children.Add(shape);}
}
